* { box-sizing: border-box; }
:root { color-scheme: dark; font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif; background: #172321; color: #f2f0e8; }
body { min-width: 360px; min-height: 100vh; margin: 0; display: grid; place-items: center; padding: 24px 16px; background: radial-gradient(ellipse at 50% 0%, #29413a 0%, #172321 65%); }
.clock-card { width: min(100%, 560px); padding: clamp(24px, 6vw, 44px); border: 1px solid #3a5148; border-radius: 20px; background: #202f2a; box-shadow: 0 24px 70px #0b1412a8; text-align: center; }
.card-header { margin-bottom: 30px; }
.eyebrow { margin: 0 0 10px; color: #d1a85d; font-size: 14px; font-weight: 750; letter-spacing: .16em; }
h1 { margin: 0; font-size: clamp(26px, 7vw, 36px); line-height: 1.15; letter-spacing: -.03em; }
.subtitle { margin: 10px 0 0; color: #bbc8bf; font-size: 16px; }
.clocks { position: relative; display: grid; grid-template-columns: 1fr 1fr; gap: 14px; }
.player-clock { min-width: 0; min-height: 190px; padding: 22px 12px 18px; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 12px; border: 2px solid #42554c; border-radius: 14px; background: #293a33; color: #f2f0e8; cursor: pointer; transition: background .15s, border-color .15s, transform .15s, box-shadow .15s; }
.player-clock:hover { border-color: #d1a85d; background: #30453b; }
.player-clock:active { transform: scale(.98); }
.player-clock:focus-visible, .controls button:focus-visible { outline: 3px solid #f3cb75; outline-offset: 3px; }
.player-clock.active { border-color: #d1a85d; background: #35483a; box-shadow: inset 0 0 0 1px #d1a85d55, 0 0 24px #d1a85d22; }
.player-clock.active .dot { background: #e7bd6c; box-shadow: 0 0 10px #e7bd6c; }
.player-clock.flagged { border-color: #db725e; background: #49312d; color: #ffd5c8; }
.player-label { display: inline-flex; align-items: center; gap: 8px; color: #c1cdc4; font-size: 14px; font-weight: 750; letter-spacing: .12em; }
.dot { width: 8px; height: 8px; border-radius: 50%; background: #718278; }
.time { font-variant-numeric: tabular-nums; font-size: clamp(38px, 10vw, 54px); font-weight: 750; line-height: 1; letter-spacing: .01em; }
.clock-hint { color: #d1a85d; font-size: 13px; font-weight: 700; letter-spacing: .1em; }
.divider { position: absolute; top: 50%; left: 50%; z-index: 1; display: grid; place-items: center; width: 34px; height: 34px; border: 1px solid #516257; border-radius: 50%; background: #202f2a; color: #aebbb1; font-size: 11px; font-weight: 800; transform: translate(-50%, -50%); }
.status { min-height: 24px; margin: 24px 0 18px; color: #c1cdc4; font-size: 16px; }
.status.is-flag { color: #f08a73; font-weight: 750; }
.controls { display: flex; justify-content: center; gap: 12px; }
.controls button { min-height: 48px; padding: 0 20px; border: 1px solid #65766a; border-radius: 10px; background: #2b3c34; color: #f2f0e8; font: inherit; font-size: 16px; font-weight: 700; cursor: pointer; transition: background .15s, border-color .15s, transform .15s; }
.controls button:hover:not(:disabled) { border-color: #d1a85d; background: #3b4d3f; }
.controls button:active:not(:disabled) { transform: translateY(1px); }
.controls button:disabled { cursor: not-allowed; opacity: .5; }
.pause-button { min-width: 130px; }
.pause-button span, .reset-button span { margin-left: 5px; }
footer { margin-top: 30px; color: #83948a; font-size: 12px; font-weight: 700; letter-spacing: .16em; }
@media (max-width: 420px) { .player-clock { min-height: 168px; padding-inline: 8px; } .player-label { font-size: 12px; } .controls button { padding-inline: 14px; } }

const START_SECONDS = 5 * 60;
const remaining = [START_SECONDS, START_SECONDS];
const clockButtons = [document.querySelector('#player-one'), document.querySelector('#player-two')];
const timeLabels = [document.querySelector('#time-one'), document.querySelector('#time-two')];
const hints = [document.querySelector('#hint-one'), document.querySelector('#hint-two')];
const status = document.querySelector('#status');
const pauseButton = document.querySelector('#pause');
const resetButton = document.querySelector('#reset');
let activePlayer = null;
let deadline = 0;
let paused = false;
let flaggedPlayer = null;
let ticker = null;

function formatTime(seconds) {
  const whole = Math.max(0, Math.ceil(seconds));
  return `${Math.floor(whole / 60)}:${String(whole % 60).padStart(2, '0')}`;
}

function render() {
  for (let i = 0; i < 2; i += 1) {
    timeLabels[i].textContent = formatTime(remaining[i]);
    clockButtons[i].classList.toggle('active', activePlayer === i && !paused);
    clockButtons[i].classList.toggle('flagged', flaggedPlayer === i);
    clockButtons[i].setAttribute('aria-pressed', String(activePlayer === i && !paused));
    clockButtons[i].setAttribute('aria-label', `Player ${i + 1} clock, ${formatTime(remaining[i])} remaining. Tap to ${activePlayer === i && !paused ? 'switch to the other player' : 'start or switch to player ' + (i + 1)}.`);
    hints[i].textContent = flaggedPlayer === i ? 'FLAG!' : activePlayer === i && !paused ? 'YOUR MOVE' : activePlayer === i && paused ? 'PAUSED' : 'TAP TO START';
  }
  pauseButton.disabled = activePlayer === null || flaggedPlayer !== null;
  pauseButton.innerHTML = paused ? '▶ <span>Resume</span>' : 'Ⅱ <span>Pause</span>';
  pauseButton.setAttribute('aria-label', paused ? 'Resume clock' : 'Pause clock');
}

function stopTicker() {
  if (ticker !== null) window.clearInterval(ticker);
  ticker = null;
}

function updateClock() {
  if (activePlayer === null || paused) return;
  const now = Date.now();
  remaining[activePlayer] = Math.max(0, (deadline - now) / 1000);
  if (remaining[activePlayer] <= 0) {
    remaining[activePlayer] = 0;
    flaggedPlayer = activePlayer;
    activePlayer = null;
    paused = false;
    stopTicker();
    status.textContent = `Flag! Player ${flaggedPlayer + 1} ran out of time.`;
    status.classList.add('is-flag');
  }
  render();
}

function startTicker() {
  stopTicker();
  ticker = window.setInterval(updateClock, 100);
}

function switchTo(player) {
  if (flaggedPlayer !== null) return;
  if (activePlayer === player && !paused) return;
  if (activePlayer !== null && !paused) {
    updateClock();
    if (flaggedPlayer !== null) return;
  }
  activePlayer = player;
  paused = false;
  deadline = Date.now() + remaining[player] * 1000;
  status.textContent = `Player ${player + 1} to move.`;
  status.classList.remove('is-flag');
  startTicker();
  render();
}

clockButtons.forEach((button, index) => button.addEventListener('click', () => switchTo(index)));
pauseButton.addEventListener('click', () => {
  if (activePlayer === null || flaggedPlayer !== null) return;
  if (!paused) {
    updateClock();
    if (flaggedPlayer !== null) return;
    paused = true;
    stopTicker();
    status.textContent = 'Clock paused.';
  } else {
    paused = false;
    deadline = Date.now() + remaining[activePlayer] * 1000;
    status.textContent = `Player ${activePlayer + 1} to move.`;
    startTicker();
  }
  render();
});
resetButton.addEventListener('click', () => {
  stopTicker();
  remaining[0] = START_SECONDS;
  remaining[1] = START_SECONDS;
  activePlayer = null;
  flaggedPlayer = null;
  paused = false;
  status.textContent = 'Choose a side to start the clock.';
  status.classList.remove('is-flag');
  render();
});

render();
